-- Supresión de maximización para todas las ventanas

hl.window_rule({
    name  = "suppress_event",
    match = {
        class = ".*",
    },
    suppress_event = "maximize",
})

-- Megasync (Xorg, RPM)

hl.window_rule({
    name  = "float",
    match = {
        class = "^(nz.co.mega.megasync)$",
    },
    float = true,
})

-- Spotify

hl.window_rule({
    name  = "float",
    match = {
        initial_class = "^(Spotify)$",
    },
    float = true,
    size = { "(monitor_w*0.6)", "(monitor_h*0.75)" },
    center = true,
})

-- Gnome Software

hl.window_rule({
    name  = "float",
    match = {
        class = "^(Gnome-software)$",
    },
    float = true,
    size = { "(monitor_w*0.6)", "(monitor_h*0.75)" },
    center = true,
})

-- Nautilus (Gnome File Manager)

hl.window_rule({
    name  = "float",
    match = {
        class = "^(org.gnome.Nautilus)$",
    },
    float = true,
    size = { "(monitor_w*0.6)", "(monitor_h*0.75)" },
    center = true,
})

