hl.bind(modShift .. " + " .. "F", hl.dsp.window.float())

hl.bind(mainMod .. " + " .. "space", hl.dsp.exec_cmd(menu))

hl.bind(mainMod .. " + " .. "P", hl.dsp.window.pseudo())

-- dwindle

hl.bind(mainMod .. " + " .. "V", hl.dsp.layout("togglesplit"))

-- dwindle

hl.bind(modShift .. " + " .. "L", hl.dsp.exec_cmd(lockScreen))

hl.bind(modShift .. " + " .. "Q", hl.dsp.exec_cmd(powerMenu))

-- SOUND

hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%+ --limit 1.0"))

hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-"))

hl.bind("XF86AudioMute", hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"))

hl.bind("XF86AudioMicMute", hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_SOURCE@ toggle"))

-- Bluetooth 

hl.bind(modShift .. " + " .. "A", hl.dsp.exec_cmd("uwsm app -- blueman-applet"))

hl.bind(mainMod .. " + " .. "A", hl.dsp.exec_cmd("killall blueman-applet &"))

-- Move focus with mainMod + arrow keys

hl.bind(mainMod .. " + " .. "left", hl.dsp.focus({ direction = "left" }))

hl.bind(mainMod .. " + " .. "right", hl.dsp.focus({ direction = "right" }))

hl.bind(mainMod .. " + " .. "up", hl.dsp.focus({ direction = "up" }))

hl.bind(mainMod .. " + " .. "down", hl.dsp.focus({ direction = "down" }))

hl.bind(mainMod .. " + " .. "f", hl.dsp.window.fullscreen())

-- Move focus with mainMod + vim motions

hl.bind(mainMod .. " + " .. "L", hl.dsp.focus({ direction = "left" }))

hl.bind(mainMod .. " + " .. "H", hl.dsp.focus({ direction = "right" }))

hl.bind(mainMod .. " + " .. "K", hl.dsp.focus({ direction = "up" }))

hl.bind(mainMod .. " + " .. "J", hl.dsp.focus({ direction = "down" }))

-- --- GAPS ADJUSTMENT ---

hl.bind(modCtrl .. " + " .. "equal", hl.dsp.exec_cmd("hyprctl keyword general:gaps_in 'add 5'"))

hl.bind(modCtrl .. " + " .. "equal", hl.dsp.exec_cmd("hyprctl keyword general:gaps_out 'add 5'"))

hl.bind(modCtrl .. " + " .. "minus", hl.dsp.exec_cmd("hyprctl keyword general:gaps_in 'sub 5'"))

hl.bind(modCtrl .. " + " .. "minus", hl.dsp.exec_cmd("hyprctl keyword general:gaps_out 'sub 5'"))

hl.bind(modCtrl .. " + " .. "0", hl.dsp.exec_cmd("hyprctl keyword general:gaps_in 4; hyprctl keyword general:gaps_out 4"))

-- Reset Gaps to initial values (4 in, 4 out)

-- Brightness

hl.bind("XF86MonBrightnessUp", hl.dsp.exec_cmd("brightnessctl set +5%"))

hl.bind("XF86MonBrightnessDown", hl.dsp.exec_cmd("brightnessctl set 5%-"))

hl.bind(modShift .. " + " .. "B", hl.dsp.exec_cmd("~/.local/bin/reloadHyprpaper"))

-- Laptop lid

