hl.bind("switch:off:Lid Switch", hl.dsp.exec_cmd("~/.config/hypr/scripts/handle_lid.sh open"), { locked = true })

hl.bind("switch:on:Lid Switch", hl.dsp.exec_cmd("~/.config/hypr/scripts/handle_lid.sh close"), { locked = true })

hl.bind(modShift .. " + " .. "P", hl.dsp.exec_cmd("~/.config/hypr/scripts/handle_lid.sh close"))

hl.bind(modShift .. " + " .. "O", hl.dsp.exec_cmd("~/.config/hypr/scripts/handle_lid.sh open"))

