-- Groups (like i3 tabbed windows)

hl.bind(mainMod .. " + " .. "t", hl.dsp.group.toggle())

hl.bind(modShift .. " + " .. "t", hl.dsp.exec_cmd("hyprctl dispatch lockactivegroup toggle"))

