-- for screen sharing

-- Autostart
hl.on("hyprland.start", function()
    hl.exec_cmd("uwsm app -- qs -c noctalia-shell")
    hl.exec_cmd("hyprctl keyword misc:allow_session_lock_restore 1")
    hl.exec_cmd("uwsm app -- hypridle")
end)

-- Exec (run every reload)
hl.on("config.reloaded", function()
    hl.exec_cmd("uwsm app -- gsettings set org.gnome.desktop.interface color-scheme \"prefer-dark\"")
end)
